mapper.select:
/* BmsBlDivideMapper.selectBmsBlDivideList : 보수BL분할 조회 */
SELECT AA.* , COUNT(*) OVER() AS TOTAL_CNT , SUM(AA.SIMPLE_CNT) OVER() AS TOTAL_SIMPLE_CNT , SUM(AA.GENERAL_CNT) OVER() AS TOTAL_GENERAL_CNT FROM ( SELECT tbh.BL5HF_NO , tbi.OD_JOB_NO , CASE WHEN (SELECT TOP 1 tcfs.REFERENCE_NO_ID FROM TB_COM_FILE_SHARE tcfs WHERE tcfs.FUNC_JOB_NO = tbi.OD_JOB_NO ) IS NULL THEN 'N' ELSE 'Y' END AS FILE_SHARE
, '통보' AS lastPodStatus , '조회' AS blStatus
, tbi.AR_DATE , tbi.CARRYIN_DATE , tbh.NOTICE_DATE , tbh.NOTICE_TIME , tbh.BL_NO , tbh.MBL_NO , tbh.CARGO_REFERENCE_NO
, tbi.CD_TYPE + '.' + (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL det WHERE det.CODE = tbi.CD_TYPE AND det.GROUP_CODE = 'CD_TYPE') AS CD_TYPE
, tbi.CD_TYPE
, IIF(tbi.CD_TYPE = 'Y', 1, 0) AS SIMPLE_CNT , IIF(tbi.CD_TYPE = 'N', 1, 0) AS GENERAL_CNT , tbh.DIVIDE_CLASS , CASE tbh.DIVIDE_CLASS WHEN '1' THEN '1.분할등록' WHEN '2' THEN '2.분할취소' WHEN '3' THEN '3.보수작업' WHEN '4' THEN '4.수입신고전물품확인' WHEN '5' THEN '5.견품반출허가' END AS DIVIDE_CLASS_NAME /* 분할구분 '코드.코드명' 형식 */ , tbi.CUSTOMS_REPORT_NO , tbh.CUSTOMS_ATTN_NAME , tbi.VESSEL_FLIGHT , tbi.VOYAGE , tbh.PKG_TYPE , ISNULL(tbh.CT, 0) AS CT , ISNULL(tbh.WT, 0) AS WT , tbh.HSN , tbi.COMMODITY_ITEM_LOC , tbi.LOCATION_PLACE , tbh.REGISTER_USER_ID , (SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = tbh.REGISTER_USER_ID) AS REGISTER_USER_NAME , tbh.REGISTER_DATE_TIME , tbi.CUSTOMER_CODE , tbi.CUSTOMER_NAME , tbi.SHIPPER_NAME , tbi.CONSIGNEE_NAME , tbi.NOTIFY_NAME , tbi.IN_PLAN_NO , tbi.IN_NO , ISNULL(D.HOLD_YN,'N') AS HOLD_YN , D.HOLD_CODE , D.HOLD_REASON , D.HOLD_RELEASE_YN , D.HOLD_RELEASE_ATTN , D.HOLD_RELEASE_DATE FROM TB_BMS_5HF tbh LEFT JOIN TB_BMS_IN tbi WITH (NOLOCK) ON tbh.CARGO_REFERENCE_NO = tbi.CARGO_REFERENCE_NO LEFT JOIN (SELECT 'Y' AS HOLD_YN , MAX(OD_JOB_NO) AS OD_JOB_NO , MAX(HOLD_CODE) AS HOLD_CODE , MAX(HOLD_REASON) AS HOLD_REASON , MAX(HOLD_RELEASE_YN) AS HOLD_RELEASE_YN , MAX(HOLD_RELEASE_ATTN) AS HOLD_RELEASE_ATTN , MAX(HOLD_RELEASE_DATE) AS HOLD_RELEASE_DATE FROM TB_ECM_OD_HOLD GROUP BY OD_JOB_NO) D ON tbi.OD_JOB_NO = D.OD_JOB_NO WHERE 1=1
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND ${srchDateGbn} >= CONVERT(CHAR(10), #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(CHAR(10), #{srchEndDate}, ${srchDateFormat}))
AND ${srchDateGbn} >= #{srchStartDate} AND ${srchDateGbn} <= #{srchEndDate}
AND tbh.DIVIDE_CLASS = #{srchDivideClass}
AND tbi.CUSTOMER_CODE = #{srchCustomerCode}
AND tbi.CUSTOMER_NAME LIKE CONCAT('%', #{srchCustomerName}, '%')
AND tbi.SHIPPER_NAME LIKE CONCAT('%', #{srchShipperName}, '%')
AND tbi.CONSIGNEE_NAME LIKE CONCAT('%', #{srchConsigneeName}, '%')
AND tbi.NOTIFY_NAME LIKE CONCAT('%', #{srchNotifyName}, '%')
AND tbi.LOCATION_PLACE LIKE CONCAT('%', #{srchLocationPlaceName}, '%')
AND tbi.COMMODITY_ITEM_LOC LIKE CONCAT('%', #{srchCommodityItemLocName}, '%')
) AA
